def unblock_relation(tasks, dependency):
    source = tasks[dependency["from"]]
    target = tasks[dependency["to"]]
    if source["status"] == "done" and target["status"] == "blocked":
        return [{
            "kind": "update",
            "id": dependency["to"],
            "changes": {"status": "ready"},
        }]
    return []
